trial.program_source:
def transform(grid):
    h,w=len(grid),len(grid[0])
    for c in [0,w-1]:
        vals=[grid[r][c] for r in range(h)]
        if 1 in vals and all(v in (0,1) for v in vals):
            block=[row[1:] if c==0 else row[:-1] for row in grid]
            return [row+[0]+row for row in block]
    for r in [0,h-1]:
        if 1 in grid[r] and all(v in (0,1) for v in grid[r]):
            block=grid[1:] if r==0 else grid[:-1]
            return [row[:] for row in block]+[[0]*w]+[row[:] for row in block]
    return [row[:] for row in grid]

